import numbers

def process_orders(orders):
    total = 0
    failed = []
    for x in orders:
        try:
            q = x.get('quantity')
            a = x.get('amount')
            if isinstance(q, int) and isinstance(a, numbers.Number):
                total += a * q
            else:
                failed.append(x['id'])
        except Exception:
            pass
    return {'revenue': total, 'failed_orders': failed}
